from typing import List

class CustomFunction:
    def __init__(self, fid):
        self.fid = fid
    def f(self, x, y):
        if self.fid == 1:
            return x + y
        elif self.fid == 2:
            return x * y
        elif self.fid == 3:
            return x * x + y
        elif self.fid == 4:
            return x + y * y


def sort_pairs(pairs):
    return sorted([list(p) for p in pairs])


