from typing import Optional, List
from collections import defaultdict, deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(values: List) -> Optional[TreeNode]:
    if not values or values[0] is None:
        return None
    root = TreeNode(values[0])
    queue = deque([root])
    i = 1
    while queue and i < len(values):
        node = queue.popleft()
        if i < len(values) and values[i] is not None:
            node.left = TreeNode(values[i])
            queue.append(node.left)
        i += 1
        if i < len(values) and values[i] is not None:
            node.right = TreeNode(values[i])
            queue.append(node.right)
        i += 1
    return root


def test_example1():
    root = build_tree([1, 5, 3, None, 4, 10, 6, 9, 2])
    assert Solution().amountOfTime(root, 3) == 4


def test_single_node():
    root = build_tree([1])
    assert Solution().amountOfTime(root, 1) == 0


def test_start_at_root():
    root = build_tree([1, 2, 3, 4, 5, 6, 7])
    assert Solution().amountOfTime(root, 1) == 2


def test_start_at_leaf():
    root = build_tree([1, 2, 3, 4, 5, 6, 7])
    assert Solution().amountOfTime(root, 4) == 4


def test_linear_tree():
    root = build_tree([1, 2, None, 3, None, 4, None, 5])
    assert Solution().amountOfTime(root, 1) == 4


def test_start_middle_linear():
    root = build_tree([1, 2, None, 3, None, 4, None, 5])
    assert Solution().amountOfTime(root, 3) == 2

